head.b:skin:
/* <Variable name="page.background" description="Page background" type="color" default="#dcc5fb" value="#dcc5fb"/><Variable name="page.text" description="Text color" type="color" default="#21122c" value="#21122c"/><Variable name="theme.accent" description="Accent color" type="color" default="#deff6f" value="#deff6f"/> */
/* Blogger stylesheet compatibility: restore the spacing Blogger's own widget stylesheet removes, and keep post content inside a phone screen. */
h1{margin:.67em 0}h2{margin:.83em 0}h3{margin:1em 0}h4{margin:1.33em 0}h1,h2,h3,h4,a img{position:static}body{padding:0;word-break:normal}.post-body{width:auto;overflow-x:auto}.post-body a[style*='margin-left'],.post-body a[style*='margin-right']{margin-inline:0!important}.post-body .separator,.post-body .tr-caption-container{max-width:100%}.widget .post-body ul,.widget .post-body ol{margin:1em 0;padding:0 0 0 1.4em;line-height:inherit}.widget .post-body li{margin:0 0 .35em;padding:0}.latest-empty{display:none}.single-view{font-size:1rem}.single-view .post-title{overflow-wrap:anywhere}
:root{--bg:$(page.background);--ink:$(page.text);--accent:$(theme.accent);--heading:'Space Grotesk', Impact, Haettenschweiler, sans-serif;--body:Arial, sans-serif}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.6 var(--body)}h1,h2,h3{font-family:var(--heading);line-height:1.15}a{color:inherit;text-underline-offset:4px}a:hover{text-decoration-thickness:2px}img{max-width:100%;height:auto}svg{max-width:100%;height:auto}button,input{font:inherit}a:focus-visible,button:focus-visible,summary:focus-visible,input:focus-visible{outline:3px solid currentColor;outline-offset:5px}a,button,summary{touch-action:manipulation}nav{max-width:100%}p,h1,h2,h3,a{overflow-wrap:anywhere}.skip-link{position:fixed;top:-100px;left:16px;z-index:100;background:var(--ink);color:var(--bg);padding:12px}.skip-link:focus{top:12px}.section,.widget{min-width:0;margin:0;padding:0;line-height:inherit}.latest{max-width:1200px;margin:64px auto;padding:0 24px}.posts-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:28px}.post-card{min-width:0}.post-title a{text-decoration:none}.post-title a:hover{text-decoration:underline}.post-media{display:block;aspect-ratio:16/10;overflow:hidden;background:color-mix(in srgb,var(--accent) 12%,var(--bg))}.post-media img{width:100%;height:100%;object-fit:cover}.post-art{height:100%;display:grid;place-items:center;font:italic 70px var(--heading);color:var(--accent)}.post-meta{margin-top:18px;font-size:12px}.post-meta a{margin-right:12px}.pager{display:flex;justify-content:space-between;gap:20px;margin-top:40px;padding-top:20px;border-top:1px solid currentColor}.pager a{padding:10px 0}.post-body{max-width:70ch;margin-inline:auto;overflow-wrap:anywhere}.post-body img,.post-body iframe{max-width:100%}.post-body pre,.post-body table{display:block;overflow:auto;max-width:100%}.single-view .latest{max-width:900px}.single-view .section-heading{display:none}.single-view .post-title{font-size:clamp(32px,5vw,62px)}.single-view #comments{margin-top:60px}.empty-state,.error-state{padding:45px 0}.error-state{max-width:900px;margin:auto;padding:70px 24px}.listing-heading{font-size:clamp(28px,5vw,52px)}#Attribution1,.widget.Attribution{display:none!important}@media(max-width:700px){.posts-grid{grid-template-columns:1fr}.latest{margin:45px auto}.pager{flex-wrap:wrap}}
a{color:inherit}a:focus-visible,summary:focus-visible{outline:3px solid currentColor;outline-offset:5px}img{max-width:100%;height:auto}svg{display:block;width:100%;height:auto} .post-title a{text-decoration:none}.post-meta{font-size:.75rem;text-transform:uppercase;letter-spacing:.12em}.post-excerpt{line-height:1.7}.post-media{overflow:hidden}.post-card{min-width:0}.post-card a:hover{text-decoration:underline}.post-card:hover .post-media{filter:saturate(1.15)}.post-media img{transition:transform .4s}.post-card:hover .post-media img{transform:scale(1.035)}@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}body{margin:0;background:#dcc5fb;color:#21122c;font-family:Arial,sans-serif}.off-nav{padding:25px 4%;display:flex;align-items:center;justify-content:space-between;border-bottom:2px solid}.off-nav .brand{font-size:26px;font-weight:900;text-decoration:none;letter-spacing:-1px}.off-nav nav{display:flex;gap:30px;font-size:12px;font-weight:bold;text-transform:uppercase}.off-nav nav a{text-decoration:none}.off-intro{padding:30px 4% 45px;position:relative;display:grid;grid-template-columns:1.05fr 1fr;gap:22px}.off-kicker{grid-column:1/-1;display:flex;justify-content:space-between;font-size:11px;letter-spacing:.15em}.off-intro h1{font-family:Impact,Haettenschweiler,sans-serif;font-size:clamp(86px,13.5vw,200px);font-weight:900;line-height:.83;letter-spacing:-.045em;margin:35px 0 0;z-index:1}.off-intro h1 em{font-style:normal;color:#ff612f;-webkit-text-stroke:2px #21122c}.off-art{align-self:center;position:relative;transform:rotate(3deg);margin:35px 0}.off-art svg{border:2px solid #21122c}.off-sticker{position:absolute;right:-8px;bottom:15px;border:2px solid;background:#deff6f;border-radius:50%;width:108px;height:108px;display:grid;place-content:center;text-align:center;font-weight:900;transform:rotate(-13deg)}.off-deck{grid-column:2;line-height:1.55;font-size:16px;margin:0}.off-ticker{background:#21122c;color:#deff6f;font-family:Impact,sans-serif;font-size:clamp(22px,4vw,55px);padding:20px 4%;white-space:nowrap;overflow:hidden;letter-spacing:.025em}.off-listening{display:grid;grid-template-columns:1fr 1.6fr;gap:60px;padding:65px 4%;background:#deff6f;border-bottom:2px solid}.off-eyebrow{font-size:10px;letter-spacing:.16em}.off-listening h2{font-size:clamp(35px,5vw,70px);line-height:1;letter-spacing:-.06em;margin:25px 0}.off-listening p{font-size:13px;line-height:1.6}.off-tracks a{border-top:2px solid;display:grid;grid-template-columns:30px 1fr 28px;gap:12px;padding:24px 0;text-decoration:none;transition:padding .2s}.off-tracks a:hover{padding-left:12px}.off-tracks strong{font-size:24px;letter-spacing:-.05em}.off-tracks small{grid-column:2;font-size:10px;letter-spacing:.09em}.off-tracks b{grid-column:3;grid-row:1/3;font-size:28px;align-self:center}.section-heading{padding:52px 4% 20px;margin:0;font-size:36px;letter-spacing:-.045em}.posts-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:30px;padding:10px 4% 65px}.post-card{border-top:2px solid;padding-top:18px}.post-media{aspect-ratio:1.5;background:#ff612f;border:2px solid;margin-bottom:18px}.post-title{font-size:26px;line-height:1.05;letter-spacing:-.04em}.post-excerpt{font-size:13px}.off-manifesto{background:#ff612f;padding:48px 4%;border-top:2px solid;border-bottom:2px solid;display:grid;grid-template-columns:1fr 3fr;gap:25px}.off-manifesto>span{font-size:11px;letter-spacing:.12em}.off-manifesto p{font-size:clamp(35px,5.3vw,74px);font-weight:900;line-height:1.03;letter-spacing:-.055em;margin:0}.off-manifesto em{font-weight:400;font-family:'Space Grotesk', Georgia,serif}.off-manifesto a{grid-column:2;font-size:11px;font-weight:bold}.off-footer{display:flex;justify-content:space-between;align-items:center;padding:35px 4%}.off-footer strong{font-size:40px;letter-spacing:-3px}.off-footer span{font-size:11px;line-height:1.7}.off-footer a{font-size:12px}@media(max-width:700px){.off-nav nav{gap:12px;font-size:9px}.off-intro{grid-template-columns:1fr}.off-intro h1{font-size:26vw}.off-art{margin:15px 5%}.off-deck{grid-column:1}.off-kicker span{display:none}.off-listening{grid-template-columns:1fr;gap:25px}.posts-grid{grid-template-columns:1fr}.off-manifesto{grid-template-columns:1fr}.off-manifesto a{grid-column:1}.off-footer strong{font-size:26px}.off-footer span{max-width:125px}} .latest{max-width:none;margin:0;padding:0}
h1,h2,h3{font-family:'Space Grotesk', Impact, Haettenschweiler, sans-serif}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto!important}*,*::before,*::after{animation:none!important;transition:none!important}.post-media img{transform:none!important}}@media print{nav,.skip-link,.pager{display:none!important}body{background:white;color:black}}
